-- PT115-S4-Q12. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT115-S4-Q12$batch03$ AND q.stimulus=$batch03$The higher a dam, the more exposed it is to forces that can cause it to collapse. Of the world’s hundreds of arch dams, more than half are over 100 meters high. Yet all six of the arch dam collapses that have occurred during the past 40 years have occurred in arch dams under 100 meters high.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, most helps to resolve the apparent paradox?$batch03$ AND q.correct_choice=$batch03$C$batch03$) THEN RAISE EXCEPTION 'Question changed: PT115-S4-Q12'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT115-S4-Q12$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT115-S4-Q12'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT115-S4-Q12$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Higher dams face more forces that can cause collapse, and more than half of arch dams are over 100 meters.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$All six arch dam collapses in 40 years were in dams under 100 meters?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$Higher dams face more risk, yet the lower ones are failing. Something must offset the risk for tall dams. If the people building tall dams know they are risky and take extra care, those dams could be safer overall.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find something that makes taller dams safer in practice despite the greater forces.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT115-S4-Q12$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$Taller dams being built as arch dams explains why many arch dams are tall. It does not explain why the short ones are the ones collapsing.$batch03$), ($batch03$B$batch03$, $batch03$Comparing arch dams with other types does not separate tall arch dams from short ones.$batch03$), ($batch03$C$batch03$, $batch03$Larger structures get more careful design and construction. That extra care can outweigh the greater forces, so tall arch dams hold while shorter ones fail.$batch03$), ($batch03$D$batch03$, $batch03$Long-known engineering principles apply to arch dams of every height.$batch03$), ($batch03$E$batch03$, $batch03$Comparing short arch dams with short dams of other types does not explain why short arch dams fail more than tall ones.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT115-S4-Q12$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
